/*
 * main_hqc2025.c
 *
 * KAT test runner for HQC-2025.
 * Uses the standard 3-arg NIST KEM API:
 *   crypto_kem_keypair(pk, sk)
 *   crypto_kem_enc(ct, ss, pk)
 *   crypto_kem_dec(ss, ct, sk)
 *
 * Randomness is generated by HQC's own SHAKE-256 PRNG (prng_get_bytes).
 * We re-seed it via prng_init(seed, NULL, 48, 0) before each iteration,
 * where `seed` is the 48-byte value stored in the .rsp file.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#include "api.h"
#include "symmetric.h"  /* prng_init */
#include "kat_parser.h"

#ifndef KATNUM
#define KATNUM  10000
#endif
/* runtime override: KATNUM env var takes precedence */
static int katnum = KATNUM;
static void __attribute__((constructor)) katnum_init(void) {
    const char *s = getenv("KATNUM"); if (s) katnum = atoi(s); }

#ifndef RUN_KEYGEN
#define RUN_KEYGEN  1
#endif
#ifndef RUN_ENCAPS
#define RUN_ENCAPS  1
#endif
#ifndef RUN_DECAPS
#define RUN_DECAPS  1
#endif
#ifndef DEBUG
#define DEBUG       0
#endif
#ifndef RSP_PATH
#error "RSP_PATH must be defined"
#endif

#if DEBUG
static void print_hex(const char *label, const uint8_t *buf, size_t len)
{
    printf("  %s = ", label);
    for (size_t i = 0; i < len; i++) printf("%02X", buf[i]);
    printf("\n");
}
#define DBGHEX(l, b, n) print_hex(l, b, n)
#else
#define DBGHEX(l, b, n) ((void)0)
#endif

int main(void)
{
    kat_parser_t parser;
    kat_entry_t  entry;

    uint8_t seed[48];

    uint8_t pk_rsp[CRYPTO_PUBLICKEYBYTES];
    uint8_t sk_rsp[CRYPTO_SECRETKEYBYTES];
    uint8_t ct_rsp[CRYPTO_CIPHERTEXTBYTES];
    uint8_t ss_rsp[CRYPTO_BYTES];

    uint8_t pk[CRYPTO_PUBLICKEYBYTES];
    uint8_t sk[CRYPTO_SECRETKEYBYTES];
    uint8_t ct[CRYPTO_CIPHERTEXTBYTES];
    uint8_t ss_enc[CRYPTO_BYTES];
    uint8_t ss_dec[CRYPTO_BYTES];

    int pass_key = 0, fail_key = 0;
    int pass_enc = 0, fail_enc = 0;
    int pass_dec = 0, fail_dec = 0;
    int count = 0, ret;

    printf("[HQC-2025] Opening .rsp: %s\n", RSP_PATH);
    if (kat_parser_open(&parser, RSP_PATH) != 0) return 1;

    printf("Testing: ");
#if RUN_KEYGEN
    printf("keygen ");
#endif
#if RUN_ENCAPS
    printf("encaps ");
#endif
#if RUN_DECAPS
    printf("decaps ");
#endif
    printf("\n");

    while (count < katnum) {
        ret = kat_parser_next(&parser, &entry);
        if (ret == 1) break;
        if (ret != 0) { fprintf(stderr, "parse error\n"); break; }

        if (kat_get_bytes(&entry, "seed", seed,   48)                         != 0) goto next;
        if (kat_get_bytes(&entry, "pk",   pk_rsp,  CRYPTO_PUBLICKEYBYTES)     != 0) goto next;
        if (kat_get_bytes(&entry, "sk",   sk_rsp,  CRYPTO_SECRETKEYBYTES)     != 0) goto next;
        if (kat_get_bytes(&entry, "ct",   ct_rsp,  CRYPTO_CIPHERTEXTBYTES)    != 0) goto next;
        if (kat_get_bytes(&entry, "ss",   ss_rsp,  CRYPTO_BYTES)              != 0) goto next;

        /* Re-seed HQC-2025's SHAKE-256 PRNG with the stored seed */
        prng_init(seed, NULL, 48, 0);

#if RUN_KEYGEN
        ret = crypto_kem_keypair(pk, sk);
        if (ret != 0 || memcmp(pk, pk_rsp, CRYPTO_PUBLICKEYBYTES) != 0
                     || memcmp(sk, sk_rsp, CRYPTO_SECRETKEYBYTES) != 0) {
            printf("[%d] FAIL: keygen\n", entry.count);
            DBGHEX("pk_got", pk, CRYPTO_PUBLICKEYBYTES);
            DBGHEX("pk_exp", pk_rsp, CRYPTO_PUBLICKEYBYTES);
            fail_key++;
        } else {
            printf("[%d] PASS: keygen\n", entry.count);
            pass_key++;
        }
#else
        memcpy(pk, pk_rsp, CRYPTO_PUBLICKEYBYTES);
        memcpy(sk, sk_rsp, CRYPTO_SECRETKEYBYTES);
#endif

#if RUN_ENCAPS
        ret = crypto_kem_enc(ct, ss_enc, pk);
        if (ret != 0 || memcmp(ct,     ct_rsp, CRYPTO_CIPHERTEXTBYTES) != 0
                     || memcmp(ss_enc, ss_rsp, CRYPTO_BYTES)            != 0) {
            printf("[%d] FAIL: encaps\n", entry.count);
            DBGHEX("ct_got",  ct,     CRYPTO_CIPHERTEXTBYTES);
            DBGHEX("ss_got",  ss_enc, CRYPTO_BYTES);
            DBGHEX("ss_exp",  ss_rsp, CRYPTO_BYTES);
            fail_enc++;
        } else {
            printf("[%d] PASS: encaps\n", entry.count);
            pass_enc++;
        }
#else
        memcpy(ct, ct_rsp, CRYPTO_CIPHERTEXTBYTES);
#endif

#if RUN_DECAPS
        ret = crypto_kem_dec(ss_dec, ct, sk);
        if (ret != 0 || memcmp(ss_dec, ss_rsp, CRYPTO_BYTES) != 0) {
            printf("[%d] FAIL: decaps\n", entry.count);
            DBGHEX("ss_got", ss_dec, CRYPTO_BYTES);
            DBGHEX("ss_exp", ss_rsp, CRYPTO_BYTES);
            fail_dec++;
        } else {
            printf("[%d] PASS: decaps\n", entry.count);
            pass_dec++;
        }
#endif

next:
        kat_entry_free(&entry);
        count++;
    }

    kat_parser_close(&parser);
    printf("\n=== Results for HQC-2025 ===\n");
#if RUN_KEYGEN
    printf("  Keygen : %d pass, %d fail\n", pass_key, fail_key);
#endif
#if RUN_ENCAPS
    printf("  Encaps : %d pass, %d fail\n", pass_enc, fail_enc);
#endif
#if RUN_DECAPS
    printf("  Decaps : %d pass, %d fail\n", pass_dec, fail_dec);
#endif
    int total_fail = fail_key + fail_enc + fail_dec;
    printf("  Total  : %d vectors, %d failures\n", count, total_fail);
    return (total_fail > 0) ? 1 : 0;
}
